 public static void Upgrade(){EditorSceneManager.OpenScene(BaseJumpAuthoring.Scene);var m=UnityEngine.Object.FindAnyObjectByType<BaseJumpMatch>();Install(m);EditorSceneManager.SaveScene(EditorSceneManager.GetActiveScene());AssetDatabase.SaveAssets();}
 public static void Scenery(Transform parent,Vector3 p,float height,bool tree,string folder){string path=tree?"Assets/JC_LP_MegaCity/Prefabs/Nature/SM_Nature_Tree_03.prefab":"Assets/Toon Gas Station/Prefabs/Rock_Cluster_1A.prefab";var source=AssetDatabase.LoadAssetAtPath<GameObject>(path);if(source==null)throw new FileNotFoundException(path);var root=new GameObject(tree?"Installed Mega City tree":"Installed Toon Gas Station rock");root.transform.SetParent(parent,false);var art=UnityEngine.Object.Instantiate(source,root.transform,false);foreach(var c in art.GetComponentsInChildren<Collider>(true))UnityEngine.Object.DestroyImmediate(c);foreach(var b in art.GetComponentsInChildren<Rigidbody>(true))UnityEngine.Object.DestroyImmediate(b);var renderers=art.GetComponentsInChildren<Renderer>();var bounds=renderers[0].bounds;foreach(var r in renderers)bounds.Encapsulate(r.bounds);float scale=height/Mathf.Max(.01f,bounds.size.y);art.transform.localScale*=scale;art.transform.localPosition-=new Vector3(bounds.center.x,bounds.min.y,bounds.center.z)*scale;root.transform.position=p;foreach(var r in renderers)if(r.sharedMaterial==null||r.sharedMaterial.shader.name=="Standard")r.sharedMaterial=SportsEventAuthoring.Mat(folder,tree?"Scenery green":"Scenery stone",tree?new Color(.19f,.32f,.12f):new Color(.28f,.31f,.32f));}
 public static void Install(BaseJumpMatch m){if(m.skyField!=null)return;const string folder="TruckBaseJumping";Directory.CreateDirectory("Assets/TruckBaseJumping/Art");AssetDatabase.Refresh();const string path="Assets/TruckBaseJumping/Art/Contoured landing valley.asset";var data=AssetDatabase.LoadAssetAtPath<TerrainData>(path);if(data==null){data=new TerrainData();AssetDatabase.CreateAsset(data,path);}data.heightmapResolution=129;data.size=new Vector3(330,65,330);var heights=new float[129,129];for(int z=0;z<129;z++)for(int x=0;x<129;x++){float px=x/128f*330-165,pz=z/128f*330-165;float radius=new Vector2(px,pz).magnitude;float blend=Mathf.SmoothStep(0,1,Mathf.InverseLerp(43,160,radius));heights[z,x]=blend*(10+Mathf.PerlinNoise(px*.025f+4,pz*.025f+6)*35)/65;}data.SetHeights(0,0,heights);data.terrainLayers=new[]{AssetDatabase.LoadAssetAtPath<TerrainLayer>("Assets/PinwheelStudio/Vista/Personal/Samples/TerrainLayers/Grass Light/Grass_Light_VistaSample.terrainlayer")};var terrain=Terrain.CreateTerrainGameObject(data).GetComponent<Terrain>();terrain.name="Contoured landing valley · Vista grass";terrain.transform.position=new Vector3(-165,0,-165);terrain.drawInstanced=true;terrain.heightmapPixelError=6;var material=SportsEventAuthoring.Mat(folder,"Valley terrain",Color.white);material.shader=Shader.Find("Universal Render Pipeline/Terrain/Lit");terrain.materialTemplate=material;if(m.ground!=null)m.ground.gameObject.SetActive(false);m.ground=terrain.GetComponent<TerrainCollider>();
 var scenery=new GameObject("Landing valley scale references").transform;for(int i=0;i<40;i++){float a=i*2.39996f,r=65+i%6*14;var p=new Vector3(Mathf.Sin(a)*r,0,Mathf.Cos(a)*r);p.y=terrain.SampleHeight(p);Scenery(scenery,p,i%3==0?4:8+i%5,i%3!=0,folder);}
 m.weatherField.clouds=m.weatherField.vendor.GetComponentInChildren<DigitalRuby.WeatherMaker.WeatherMakerFullScreenCloudsScript>(true);m.weatherField.cloudProfiles=SportsChaosAuthoring.CloudProfiles(folder,true);var field=m.gameObject.AddComponent<BaseSkyField>();field.match=m;m.skyField=field;field.bodies=new BaseSkyBody[24];field.blasts=new ParticleSystem[6];var flare=SportsChaosAuthoring.Flare(folder);for(int i=0;i<6;i++){var fx=new GameObject("Pooled sky explosion "+i).AddComponent<ParticleSystem>();SportsChaosAuthoring.FixBlast(fx,flare);field.blasts[i]=fx;}var contact=SportsEventAuthoring.Contact(folder,"Falling object contact",.25f,.16f);var dark=SportsEventAuthoring.Mat(folder,"Sky wreckage",new Color(.24f,.19f,.11f));var hot=SportsEventAuthoring.Mat(folder,"Telegraphed incoming projectile",new Color(1,.22f,.025f));hot.EnableKeyword("_EMISSION");hot.SetColor("_EmissionColor",new Color(1,.1f,.015f)*2);
 for(int i=0;i<24;i++){int kind=i<8?1:i>=20?2:0;GameObject g;if(kind==1){g=(GameObject)PrefabUtility.InstantiatePrefab(AssetDatabase.LoadAssetAtPath<GameObject>("Assets/TruckCheeseRolling/Prefabs/ExplosiveSheep.prefab"));PrefabUtility.UnpackPrefabInstance(g,PrefabUnpackMode.Completely,InteractionMode.AutomatedAction);var old=g.GetComponent<CheeseSheep>();if(old.warning!=null)old.warning.SetActive(false);UnityEngine.Object.DestroyImmediate(old);g.name="Falling actual SheepV5 "+i;}else{g=SportsEventAuthoring.Box(kind==2?"Telegraphed sky projectile "+i:"Physical falling crate "+i,Vector3.zero,kind==2?new Vector3(.35f,.35f,1.8f):new Vector3(1.3f,1.3f,1.3f),kind==2?hot:dark,contact);if(kind==0){var art=new GameObject("Installed crate visual");art.transform.SetParent(g.transform,false);art.transform.localScale=Vector3.one/1.3f;LWS.TruckKeepaway.Editor.KeepawayChaosAuthoring.Art(art,"Assets/IndieKit/Crates and Barrels/Prefabs/Non-Destructible/crate_01.prefab",dark);g.GetComponent<Renderer>().enabled=false;}}
 var body=g.GetComponent<Rigidbody>();if(body==null)body=g.AddComponent<Rigidbody>();body.mass=kind==0?1.5f:.6f;body.useGravity=kind!=2;body.linearDamping=.03f;body.angularDamping=.04f;body.maxAngularVelocity=6;body.maxLinearVelocity=45;body.collisionDetectionMode=CollisionDetectionMode.ContinuousDynamic;body.interpolation=RigidbodyInterpolation.Interpolate;var item=g.AddComponent<BaseSkyBody>();item.field=field;item.body=body;item.index=i;item.kind=kind;field.bodies[i]=item;if(kind==2||i%5==0){var trail=g.AddComponent<TrailRenderer>();trail.sharedMaterial=flare;trail.time=kind==2?1.2f:.5f;trail.startWidth=kind==2?.7f:.35f;trail.endWidth=.02f;trail.startColor=Color.yellow;trail.endColor=new Color(1,.1f,0,0);item.trail=trail;}g.SetActive(false);}
 foreach(var fx in m.jumpers)SportsChaosAuthoring.FixBlast(fx.crash,flare);EditorUtility.SetDirty(m);Debug.Log("BASE_SKY_SAVED bounded24 physical hazards, SheepV5, crates, trails, Vista valley");}
